function alignButtons(){return `<div class="section-label">对齐与分布 <span class="muted">${selectedLeaves().length<2?'相对页面':'相对所选'}</span></div><div class="align-grid">${[['left','左对齐','⊣'],['centerX','水平居中','╋'],['right','右对齐','⊢'],['top','上对齐','⊤'],['centerY','垂直居中','╂'],['bottom','下对齐','⊥'],['gapX','水平等距','⋯'],['gapY','垂直等距','⋮']].map(([k,t,i])=>`<button data-align="${k}" title="${t}" ${['gapX','gapY'].includes(k)&&selectedLeaves().length<3?'disabled':''}>${i}</button>`).join('')}</div>`;}
function refresh(full=true){renderBoard();renderProps();if(full){renderTabs();renderLayers();renderTools();}refreshUndo();}
function selectIDs(ids,refreshUI=true){selection=new Set(ids.filter(id=>!!getNode(id)));if(refreshUI)refresh();}
