function group(){let ids=[...selection].filter(id=>getNode(id));ids=ids.filter(id=>!ids.some(other=>id!==other&&descendants(other).some(x=>x.id===id)));if(ids.length<2){status('请先选择两个或更多图层');return;}saveHistory();const g={id:uid(),kind:'group',name:'编组 '+(page.nodes.filter(n=>n.kind==='group').length+1),visible:true,locked:false};const chosen=new Set(ids.flatMap(id=>[id,...descendants(id).map(n=>n.id)])),original=page.nodes,max=original.reduce((m,n,i)=>chosen.has(n.id)?i:m,-1),ordered=original.filter(n=>chosen.has(n.id));page.nodes=original.filter(n=>!chosen.has(n.id));const at=max+1-original.slice(0,max+1).filter(n=>chosen.has(n.id)).length;page.nodes.splice(at,0,...ordered,g);for(const id of ids)getNode(id).parentId=g.id;selection=new Set([g.id]);dirty();refresh();}
